MydesBridge.decorateUnits('grid-shelf-view-model.ytGridShelfViewModelHost.item, div.ytGridShelfViewModelGridShelfRow.item, ytm-shorts-lockup-view-model.shortsLockupViewModelHost, ytm-video-with-context-renderer.item.adaptive-feed-item, [data-mydes="card"]', '<svg class="mydes-pauldron" viewBox="0 0 64 64" style="position:absolute;left:-8px;top:-8px;width:36px;height:36px;pointer-events:none;filter:drop-shadow(0 0 4px #2EE674);"><polygon points="32,2 62,16 62,48 32,62 2,48 2,16" fill="#132E22" stroke="#F5D033" stroke-width="2"/><line x1="32" y1="2" x2="32" y2="62" stroke="#2EE674" stroke-width="1" opacity="0.6"/></svg><svg class="mydes-coin" viewBox="0 0 48 48" style="position:absolute;right:-10px;top:50%;transform:translateY(-50%);width:28px;height:28px;pointer-events:none;filter:drop-shadow(0 0 4px #F5D033);"><circle cx="24" cy="24" r="22" fill="#F5D033"/><text x="24" y="30" text-anchor="middle" font-family="Orbitron" font-size="16" fill="#0B1D15" font-weight="700">★</text></svg>');
