{"concept":"The page is a sunken Atlantean monolith glowing with hydrothermal power and ancient gold inscriptions.","fingerprint":"Serif font, abyssal cyan gold palette, coral shapes, trench cascade layout","needsHud":false,"hudReason":"","id":"8fcd52915d3e","name":"Atlantean Aquaman YouTube","dark":true,"bg":"#051c24","surface":"#0a3a40","surface2":"#062830","fg":"#ffffff","ink":"#e5af42","accent":"#11999e","remapSurfaces":true,"customCss":"html { background-color: var(--m-bg) !important; color: var(--m-fg) !important; }
body, main, [data-mydes="main"], [data-mydes="grid"], lazy-list { background-color: transparent !important; }

/* Header & Search */
header, [data-mydes="header"] {
 background: linear-gradient(135deg, #051c24 0%, #0a3a40 100%) !important;
 border-bottom: 2px solid var(--m-ink) !important;
 box-shadow: 0 4px 20px rgba(17,153,158,0.4) !important;
 position: sticky !important;
 top: 0 !important;
 z-index: 100 !important;
}
[data-mydes="search"], input[type="text"], input[type="search"], form {
 background: #020d12 !important;
 border: 2px solid var(--m-accent) !important;
 border-radius: 4px !important;
 color: var(--m-fg) !important;
 box-shadow: inset 0 2px 5px rgba(0,0,0,0.8), 0 0 10px rgba(17,153,158,0.3) !important;
}

/* Layout - Ocean Trench Cascade */
lazy-list, [data-mydes="grid"], .ytGridShelfViewModelGridShelfRow {
 display: grid !important;
 grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)) !important;
 gap: 20px !important;
 width: 100% !important;
 max-width: 100% !important;
 box-sizing: border-box !important;
 padding: 16px !important;
}

/* Cards & Repeated Items */
ytm-video-with-context-renderer.item.adaptive-feed-item, ytm-media-item, [data-mydes="card"], div.ytGridShelfViewModelGridShelfItem {
 background-color: var(--m-surface) !important;
 border: 2px solid var(--m-accent) !important;
 border-radius: 8px !important;
