MydesBridge.enable3DTilt(12);"}

{"concept":"A 1940s Brooklyn USO recruitment dossier and vintage scrapboard celebrating Captain America's timeless heroics.","fingerprint":"Monospace stencil serif, patriotic vintage palette, tactical paper shapes, pinned telegram corkboard layout","needsHud":false,"hudReason":"","id":"30f0a456e2d2","name":"Captain America 1940s USO Dossier","dark":true,"bg":"#0a192f","surface":"#1e3a8a","surface2":"#112240","fg":"#e2e8f0","ink":"#fbbf24","accent":"#dc2626","remapSurfaces":true,"customCss":":root{--m-bg:#0a192f;--m-surface:#1e3a8a;--m-surface2:#112240;--m-fg:#e2e8f0;--m-ink:#fbbf24;--m-accent:#dc2626;--m-rx:0deg;--m-ry:0deg;--m-scroll:0px;}html{background-color:var(--m-bg)!important;}body,main,[data-mydes="main"],[data-mydes="grid"]{background-color:transparent!important;}/* header */header,[data-mydes="header"]{background:linear-gradient(180deg,#3b2f2f,#2a1f1f)!important;border-bottom:4px solid var(--m-accent)!important;box-shadow:0 4px 12px rgba(0,0,0,.6)!important;padding:12px!important;font-family:Impact,sans-serif!important;color:var(--m-ink)!important;text-transform:uppercase!important;letter-spacing:1px!important;}/* search */input[type="search"],[data-mydes="search"] input{background:#111!important;border:2px solid var(--m-accent)!important;color:var(--m-fg)!important;font-family:"Courier New",monospace!important;font-size:14px!important;padding:8px 12px!important;width:100%!important;box-sizing:border-box!important;outline:none!important;}input[type="search"]::placeholder{color:#888!important;font-style:italic!important;}/* headings */h1,h2,h3,h4,[data-mydes="heading"],[data-mydes="title"]{font-family:Impact,sans-serif!important;color:var(--m-ink)!important;text-transform:uppercase!important;letter-spacing:1px!important;-webkit-line-clamp:unset!important;line-clamp:unset!important;max-height:none!important;height:auto!important;overflow:visible!important;display:block!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;}/* grid containers */lazy-list,[data-mydes="grid"]{display:grid!important;grid-template-columns:repeat(auto-fill,minmax(160px,1fr))!important;gap:16px!important;padding:16px!important;width:100%!important;max-width:100%!important;box-sizing:border-box!important;}/* cards */[data-mydes="card"],ytm-video-with-context-renderer.item.adaptive-feed-item,div.ytGridShelfViewModelGridShelfItem,div.ytGridShelfViewModelGridShelfRow.item{background:var(--m-surface)!important;border:3px solid var(--m-accent)!important;border-radius:4px!important;box-shadow:6px 6px 0 rgba(0,0,0,.5),12px 12px 24px rgba(0,0,0,.4)!important;padding:12px!important;position:relative!important;transform:rotateX(var(--m-rx)) rotateY(var(--m-ry))!important;transform-origin:center!important;transition:transform .15s linear,box-shadow .2s!important;min-width:0!important;max-width:100%!important;box-sizing:border-box!important;font-family:"Courier New",monospace!important;color:var(--m-fg)!important;}/* rivet corners */[data-mydes="card"]::before,[data-mydes="card"]::after,ytm-video-with-context-renderer.item.adaptive-feed-item::before,ytm-video-with-context-renderer.item.adaptive-feed-item::after{content:""!important;position:absolute!important;width:10px!important;height:10px!important;background:#332!important;border:2px solid #554!important;border-radius:50%!important;box-shadow:inset -1px -1px 2px rgba(0,0,0,.6)!important;}[data-mydes="card"]::before,ytm-video-with-context-renderer.item.adaptive-feed-item::before{top:-5px!important;left:-5px!important;}[data-mydes="card"]::after,ytm-video-with-context-renderer.item.adaptive-feed-item::after{bottom:-5px!important;right:-5px!important;}/* coffee stain texture */[data-mydes="card"],ytm-video-with-context-renderer.item.adaptive-feed-item,div.ytGridShelfViewModelGridShelfItem{background-image:radial-gradient(circle at 20% 30%,rgba(139,90,43,.08) 2px,transparent 2px),radial-gradient(circle at 80% 70%,rgba(139,90,43,.06) 1px,transparent 1px)!important;background-size:60px 60px,40px 40px!important;}/* thumbnail */[data-mydes="card"] img,ytm-video-with-context-renderer.item.adaptive-feed-item img{width:100%!important;height:auto!important;display:block!important;border-radius:2px!important;}/* title under thumbnail */[data-mydes="card"] h3,[data-mydes="card"] [id*="title"],ytm-video-with-context-renderer.item.adaptive-feed-item h3{margin:8px 0 4px!important;font-size:13px!important;line-height:1.3!important;color:var(--m-fg)!important;}/* view count badge */[data-mydes="card"] .metadata,ytm-video-with-context-renderer.item.adaptive-feed-item .metadata{font-size:11px!important;color:var(--m-ink)!important;display:flex!important;align-items:center!important;gap:4px!important;}/* links */a,[data-mydes="card"] a{color:var(--m-accent)!important;text-decoration:none!important;text-shadow:0 0 4px var(--m-accent)!important;transition:color .2s!important;}a:hover,a:focus{color:var(--m-ink)!important;text-shadow:0 0 8px var(--m-ink)!important;}/* buttons */button,[data-mydes="btn"]{background:linear-gradient(180deg,#444,#222)!important;border:3px solid #555!important;color:var(--m-fg)!important;font-family:Impact,sans-serif!important;text-transform:uppercase!important;padding:10px 16px!important;box-shadow:4px 4px 0 rgba(0,0,0,.6)!important;cursor:pointer!important;transition:transform .08s,box-shadow .08s!important;}button:active,[data-mydes="btn"]:active{transform:translate(2px,2px)!important;box-shadow:2px 2px 0 rgba(0,0,0,.6)!important;}/* red string connectors (visual only) */[data-mydes="grid"]::after{content:""!important;position:absolute!important;top:0;left:0;width:100%;height:100%;background:repeating-linear-gradient(45deg,transparent,transparent 30px,rgba(220,38,38,.07) 30px,rgba(220,38,38,.07) 31px)!important;pointer-events:none!important;z-index:0!important;}
