{"concept":"A morphin grid command center melding Dragon Zord green gold armor with White Ranger Tiger thunder plates.","fingerprint":"Rajdhani techno font, green gold armor palette, hexagonal chevron shapes, morpher weapon rack layout","needsHud":false,"hudReason":"","id":"f6a0e8b7aba6","name":"Morphin Grid Command Center","dark":true,"bg":"#0b1d15","surface":"#132e22","surface2":"#1a3a2e","fg":"#e2f6ed","ink":"#e2f6ed","accent":"#f5d033","remapSurfaces":true,"customCss":"
:root{--m-bg:#0B1D15;--m-surface:#132E22;--m-surface2:#1A3A2E;--m-fg:#E2F6ED;--m-ink:#E2F6ED;--m-accent:#F5D033;--m-primary:#2EE674;--m-rx:0deg;--m-ry:0deg;--m-scroll:0px;}
html{background-color:var(--m-bg)!important;}
body,[data-mydes="main"],[data-mydes="grid"]{background-color:transparent!important;}
/* Header – Morpher HUD */
header.mobile-topbar-header.cairo-settings-topbar{background:linear-gradient(135deg,var(--m-surface),var(--m-surface2))!important;border-bottom:2px solid var(--m-accent)!important;box-shadow:0 4px 12px rgba(46,230,116,0.3)!important;position:relative;}
header.mobile-topbar-header.cairo-settings-topbar::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 4px,rgba(245,208,51,0.03) 4px,rgba(245,208,51,0.03) 8px);pointer-events:none;}
/* Search – Dragon Dagger scanner */
yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb{background:var(--m-bg)!important;border:2px solid var(--m-primary)!important;border-radius:8px!important;padding:6px 12px!important;color:var(--m-fg)!important;font-family:'Rajdhani',sans-serif!important;text-transform:uppercase!important;letter-spacing:0.08em!important;box-shadow:0 0 8px var(--m-primary)!important;}
yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb input{color:var(--m-fg)!important;background:transparent!important;}
/* Layout – grid containers */
lazy-list,[data-mydes="grid"]{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px!important;width:100%!important;max-width:100%!important;box-sizing:border-box!important;}
div.ytGridShelfViewModelGridShelfItem{grid-column:auto!important;}
/* Full‑width vertical / horizontal cards */
grid-shelf-view-model.ytGridShelfViewModelHost.item,
div.ytGridShelfViewModelGridShelfRow.item,
ymt-video-with-context-renderer.item.adaptive-feed-item{display:flex!important;flex-direction:column!important;width:100%!important;max-width:100%!important;box-sizing:border-box!important;min-width:0!important;}
/* Compact tiles */
ymt-shorts-lockup-view-model.shortsLockupViewModelHost{width:100%!important;max-width:100%!important;box-sizing:border-box!important;min-width:0!important;}
/* Card surface – armored plate */
[data-mydes="card"],
grid-shelf-view-model.ytGridShelfViewModelHost.item,
div.ytGridShelfViewModelGridShelfRow.item,
ymt-shorts-lockup-view-model.shortsLockupViewModelHost,
ymt-video-with-context-renderer.item.adaptive-feed-item{background:linear-gradient(145deg,var(--m-surface),var(--m-surface2))!important;border:2px solid var(--m-primary)!important;border-radius:12px!important;box-shadow:0 6px 18px rgba(46,230,116,0.25), inset 0 1px 0 rgba(245,208,51,0.2)!important;clip-path:polygon(8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px), 0 8px)!important;position:relative;overflow:visible!important;}
/* Media wrapper – stretch */
a.shortsLockupViewModelHostEndpoint.reel-item-endpoint,
img.ytCoreImageHost.video-thumbnail-img{width:100%!important;height:auto!important;display:block!important;}
/* Thumbnail glow on hover */
a.shortsLockupViewModelHostEndpoint.reel-item-endpoint:hover img,
img.ytCoreImageHost.video-thumbnail-img:hover{filter:brightness(1.15) drop-shadow(0 0 12px var(--m-primary)) drop-shadow(0 0 24px var(--m-accent))!important;transition:filter 0.3s ease!important;}
/* Titles – Orbitron / Rajdhani uppercase glowing */
h3.shortsLockupViewModelHostMetadataTitle.shortsLockupViewModelHostMetadataTitleHasBottomMetadata,
h3.media-item-headline,[data-mydes="title"]{font-family:'Orbitron','Rajdhani',sans-serif!important;font-weight:700!important;text-transform:uppercase!important;letter-spacing:0.1em!important;color:var(--m-fg)!important;text-shadow:0 0 6px var(--m-primary),0 0 12px var(--m-accent)!important;-webkit-line-clamp:unset!important;line-clamp:unset!important;max-height:none!important;height:auto!important;overflow:visible!important;display:block!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;}
/* Bottom bar – frosted glass armor */
ymt-pivot-bar-renderer.frosted-glass{background:rgba(19,46,34,0.85)!important;backdrop-filter:blur(12px)!important;border-top:1px solid var(--m-primary)!important;box-shadow:0 -4px 16px rgba(46,230,116,0.2)!important;}
/* 3D tilt variables usage */
[data-mydes="card"]{transform:perspective(800px) rotateX(var(--m-rx)) rotateY(var(--m-ry))!important;transition:transform 0.1s linear!important;}
