 seal.innerHTML = '<svg width="36" height="36" viewBox="0 0 36 36" style="position:absolute; top:-12px; right:-12px; z-index:10; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.8));"><circle cx="18" cy="18" r="16" fill="#8b0000" stroke="#d4af37" stroke-width="2"/><text x="18" y="23" text-anchor="middle" fill="#d4af37" font-size="14" font-family="Cinzel, serif">W</text></svg>';
