{"concept":"A Targaryen conqueror's war tent draped in dragon-scale leather and smoldering embers.","fingerprint":"Cinzel serif, Targaryen crimson-gold palette, dragon-scale shapes, war-table column layout","needsHud":false,"hudReason":"","id":"7fcc3dbe8df3","name":"Daenerys Targaryen – Mother of Dragons","dark":true,"bg":"#0b0c10","surface":"#1f2833","surface2":"#1f2833","fg":"#c5a059","ink":"#e6af2e","accent":"#8b0000","remapSurfaces":true,"customCss":"
:root{
 --m-bg:#0b0c10;
 --m-surface:#1f2833;
 --m-surface2:#1f2833;
 --m-fg:#c5a059;
 --m-ink:#e6af2e;
 --m-accent:#8b0000;
 --m-rx:0deg;
 --m-ry:0deg;
 --m-scroll:0px;
}
html{background-color:var(--m-bg)!important;}
body,main,[data-mydes="main"],[data-mydes="grid"]{background-color:transparent!important;color:var(--m-fg);font-family:'Cormorant Garamond',serif;}
/* Header – bronze‑riveted war banner */
header.mobile-topbar-header.cairo-settings-topbar{
 position:relative;
 background:linear-gradient(180deg,#1f2833 0%,#0b0c10 100%)!important;
 border-bottom:3px solid var(--m-accent)!important;
 box-shadow:0 4px 12px rgba(139,0,0,0.6), inset 0 -2px 6px rgba(197,160,89,0.3)!important;
 z-index:10;
}
header.mobile-topbar-header.cairo-settings-topbar::before,
header.mobile-topbar-header.cairo-settings-topbar::after{
 content:'';
 position:absolute;
 bottom:-3px;
 width:12px;height:12px;
 border-radius:50%;
 background:radial-gradient(circle at 30% 30%,#c5a059,#8b0000);
 box-shadow:0 0 4px #c5a059;
}
header.mobile-topbar-header.cairo-settings-topbar::before{left:12px;}
header.mobile-topbar-header.cairo-settings-topbar::after{right:12px;}
/* Search bar – embossed parchment scroll */
yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb{
 background:#1f2833!important;
 border:2px solid var(--m-fg)!important;
 border-radius:6px!important;
 box-shadow:inset 0 2px 6px rgba(0,0,0,0.7),0 0 8px rgba(197,160,89,0.4)!important;
 padding:6px 12px!important;
 color:var(--m-ink)!important;
 font-family:'Cormorant Garamond',serif!important;
 font-size:15px!important;
}
yt-searchbox.ytSearchboxComponentHost.ytSearchboxComponentMweb:focus-within{
 box-shadow:inset 0 2px 6px rgba(0,0,0,0.7),0 0 12px var(--m-accent)!important;
 border-color:var(--m-accent)!important;
}
/* Container – vertical war‑table column */
lazy-list{
 display:flex!important;
 flex-direction:column!important;
 gap:0!important;
 padding:12px!important;
}
/* Card – overlapping iron shields */
ytm-video-with-context-renderer.item.adaptive-feed-item,
[data-mydes="card"]{
 width:100%!important;
 max-width:100%!important;
 box-sizing:border-box!important;
 background:var(--m-surface)!important;
 border:2px solid var(--m-fg)!important;
 border-radius:0!important;
 clip-path:polygon(8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px), 0 8px)!important;
 box-shadow:inset 0 0 12px var(--m-accent),0 4px 10px rgba(0,0,0,0.6)!important;
 position:relative;
 margin-bottom:-16px!important;
 transform:perspective(1000px) rotateX(var(--m-rx)) rotateY(var(--m-ry));
 transition:box-shadow .3s,border-color .3s;
 z-index:1;
}
ytm-video-with-context-renderer.item.adaptive-feed-item:hover,
[data-mydes="card"]:hover{
 box-shadow:inset 0 0 20px var(--m-accent),0 8px 20px rgba(139,0,0,0.8)!important;
 border-color:var(--m-accent)!important;
}
/* Thumbnail */
ytm-video-with-context-renderer.item.adaptive-feed-item img.ytCoreImageHost.video-thumbnail-img,
[data-mydes="card"] img.ytCoreImageHost.video-thumbnail-img{
 width:100%!important;
 height:auto!important;
 display:block;
}
/* Title */
h3.media-item-headline,[data-mydes="title"]{
 font-family:'Cinzel Decorative',cursive!important;
 text-transform:uppercase!important;
 letter-spacing:0.1em!important;
 color:var(--m-fg)!important;
 text-shadow:0 2px 4px rgba(0,0,0,0.9)!important;
 -webkit-line-clamp:unset!important;line-clamp:unset!important;max-height:none!important;height:auto!important;overflow:visible!important;display:block!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;
 margin:8px 12px 4px!important;
}
/* Body text */
[data-mydes="card"] p,[data-mydes="card"] span{
 color:var(--m-ink)!important;
 font-family:'Cormorant Garamond',serif!important;
 line-height:1.5!important;
}
/* Links & buttons */
a,[data-mydes="btn"],button{
 color:var(--m-fg)!important;
 background:transparent!important;
 border:1px solid var(--m-fg)!important;
 border-radius:4px!important;
 padding:6px 12px!important;
 font-family:'Cinzel Decorative',cursive!important;
 text-transform:uppercase!important;
 letter-spacing:0.08em!important;
 transition:background .2s,color .2s;
}
a:hover,[data-mydes="btn"]:hover,button:hover{
 background:var(--m-accent)!important;
 color:var(--m-bg)!important;
 border-color:var(--m-accent)!important;
}
/* Bottom bar */
ytm-pivot-bar-renderer.frosted-glass{
 background:var(--m-surface)!important;
 border-top:2px solid var(--m-fg)!important;
 box-shadow:0 -4px 12px rgba(139,0,0,0.4)!important;
}
/* Dragon‑scale crest positioning */
.dragon-crest{filter:drop-shadow(0 0 4px #c5a059);}
/* Wing divider mask */
@supports (-webkit-mask:url(#wingMask)) or (mask:url(#wingMask)){
 .wing-divider{-webkit-mask:url(#wingMask);mask:url(#wingMask);}
}
/* Amber particles already injected via JS */
.amber-particles{pointer-events:none;}
