 <circle cx="8" cy="8" r="4" fill="#00FF66" opacity="0.9" style="filter:drop-shadow(0 0 4px #00FF66);">
 <animate attributeName="opacity" values="0.9;0.3;0.9" dur="1.5s" repeatCount="indefinite"/>
 </circle>
 </svg>
 <svg class="mydes-rivets" viewBox="0 0 100 100" style="position:absolute;bottom:4px;left:4px;width:12px;height:12px;pointer-events:none;z-index:5;">
 <circle cx="6" cy="6" r="3" fill="#D4AF37" stroke="#080E0A" stroke-width="0.5"/>
 </svg>
 <svg class="mydes-rivets" viewBox="0 0 100 100" style="position:absolute;bottom:4px;right:4px;width:12px;height:12px;pointer-events:none;z-index:5;">
