MydesBridge.injectOrnament('[data-mydes="header"], header', `
 <div class="mydes-morpher-dial" style="position:absolute;top:50%;right:16px;transform:translateY(-50%);width:48px;height:48px;pointer-events:none;z-index:10;">
 <svg viewBox="0 0 100 100" width="100%" height="100%">
 <circle cx="50" cy="50" r="45" fill="#0F1A0C" stroke="#D4AF37" stroke-width="3"/>
 <circle cx="50" cy="50" r="35" fill="none" stroke="#00FF66" stroke-width="2" stroke-dasharray="10 6" class="rot"/>
 <circle cx="50" cy="50" r="18" fill="#00FF66" opacity="0.5" class="pulse"/>
 </svg>
 <style>
 .rot { animation: spin 3s linear infinite; transform-origin:center; transform-box:fill-box; }
 .pulse { animation: pulse 1.8s ease-in-out infinite; transform-origin:center; transform-box:fill-box; }
 @keyframes spin { to { transform: rotate(360deg);} }
 @keyframes pulse { 0%,100% { opacity:.4; transform:scale(1);} 50% { opacity:1; transform:scale(1.2);} }
 </style>
 </div>
`, "append");
MydesBridge.enable3DTilt(12);"}
